item.content:encoded:
/* Hide desktop menu on mobile and tablet - show hamburger instead */
@media (max-width: 1024px) {
    #mainmenu {
        display: none !important;
    }
}

/* Ensure hamburger menu icon is visible on mobile */
@media (max-width: 1024px) {
    .restly-mobile-menu-toggle,
    .mobile-menu-icon,
    .menu-toggle,
    button.restly-mobile-nav-icon {
        display: block !important;
        visibility: visible !important;
        opacity: 1 !important;
    }
}

/* Disable sticky navigation on desktop */
@media (min-width: 1025px) {
    .elementor-sticky, 
    .elementor-sticky--active,
    header[data-elementor-sticky],
    .restly-header-area.sticky,
    .site-header.sticky {
        position: relative !important;
        top: auto !important;
    }
}

/* Set sticky menu background to white */
#sticky-header {
	    background-color: white !important;
	    left: 0 !important;
	    right: 0 !important;
	    width: 100% !important;
	    padding-left: 0 !important;
	    margin-left: 0 !important;
	}



/* Change all link hover colors to match button green */
a:hover {
	    color: #006666 !important;
	}
